  4→import type { Criterion, ReviewActionRequest } from '../hooks/useReviews';
  5→import { cn } from '../lib/utils';
  6→import { CriterionAuditHistory } from './CriterionAuditHistory';
  7→import CriterionModifyDialog from './CriterionModifyDialog';
  8→import { CriterionRerunPanel } from './CriterionRerunPanel';
  9→import FieldMappingBadges from './FieldMappingBadges';
 10→import RejectDialog from './RejectDialog';
 11→import { DEFAULT_FIELD_VALUES } from './structured-editor/constants';
